const M4 = "Literary analysis keeps the focus on the text: “The poem’s falling rhythm creates…”, not “I feel the poem is sad.”";
const M5 = "A strong argument meets the best objection fairly, then answers it. Attacking opponents loses readers.";
const M6 = "A personal essay <em>discovers</em> its meaning. Scene, turn, reflection, and the insight is earned, not announced.";
